DO $$ BEGIN COMMENT ON TABLE audit.database_history IS 'Per-database Flyway-style audit log of every DDL/DML migration script that ran against this DB. One row per migration attempt: script_file, description, status, started_by_user, captured script_output, runtime metrics (started_date/stop_date/execution_time_ms/row_count), and on failure the errors text. The database text column lets ops aggregate cross-database runs into one audit stream. PK: id (from audit.database_history_id_seq).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application IS 'Registered aiWARE application — one row per app a user/org can launch (built-in apps, customer-built apps, partner integrations). Carries identity (application_id uuid PK, application_name, application_key text — the URL-safe identifier, application_description), presentation (application_icon_url/application_icon_svg, application_order), launch target (application_url), lifecycle (application_status enum: draft/active/disabled/deleted/pending/approved), tenancy (owner_organization_id, deployment_model), authZ defaults (application_check_permissions, permissions_required), OAuth2 config (oauth2_redirect_urls, oauth2_client_secret), and event-handling config (event_endpoint, metadata_version). Created-time/updated-time stored as integer epoch seconds. Joined heavily by admin/permission queries.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application__application_category IS 'Application ↔ application_category junction: two-column table (application_id, application_category_id) for tagging apps into one or more catalog categories (e.g. "Analytics", "Ingestion", "Workflow"). Joined to display category-filtered app lists in the catalog UI.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application__organization IS 'Application ↔ organization grant: one row per (application_id, organization_id) pair, indicating the org has been granted access to (or installed) the application. Carries the install/billing metadata accumulated by later migrations: type (enum organization_application_type_enum, default ''org''), business_unit (varchar 50), created_date/modifed_date (note typo: modifed_date, not modified_date — preserved from V3_19__billing.sql), event_handler_user_id (FK to sso_user.user_id, set NULL on user delete) added in V3_41 for app event-scheduling. The primary aiware-core read surface for "which apps does this org have?".'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application__organization_setting IS 'Per-(application, organization) key-value setting store. Added in V3_23__application_setting_table.sql. PK is the triple (application_id, organization_guid, key). key is the setting name, type is a free-text type tag (e.g. string, int, bool, json), description is optional human-readable doc, value is the serialized value (text — caller interprets per type). Note: scoped by organization_guid (uuid), not organization_id (integer) — uses the newer guid-based org identity introduced for cross-cluster identity reconciliation.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application_category IS 'Catalog category for grouping application rows (e.g. "Analytics", "Workflow", "Ingestion"). Two-column lookup: application_category_id (uuid PK), application_category_name (text). Junction application__application_category links apps to categories.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application_context_menu IS 'Per-application context-menu / overflow-menu entry. One row per (application, menu-item) pair: application_context_menu_id (uuid PK), application_id FK, type (enum contextmenutype), label (varchar 255), url (varchar 255, optional — when null, the menu item is a placeholder). Renders in the app UI''s contextual menus.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.application_metadata IS 'Per-(application, metadata-type) extra metadata jsonb blob. PK is the pair (application_id, type). type (varchar) discriminates the blob''s purpose (e.g. manifest, permissions, event_schema); content (jsonb NOT NULL) is the body. Added in V3_101__add_application_metadata.sql (DROP CASCADE then CREATE — implies a prior schema variant was replaced).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.external_credential IS 'Externally-issued credential the platform stores on behalf of an organization (e.g. an AWS S3 access key, an OAuth token to a 3rd-party service). One row per credential: external_credential_id (text PK — externally-meaningful id), credential_name (human label), organization_id (text, owning tenant), created_by (text user), service_type (enum service_type, default ''s3''). credentials_ciphertext holds the encrypted blob; encryption_key_id identifies the KMS/KEK that wraps it. session_expiration (epoch seconds) lets short-lived creds expire. Standard created_date / updated_date (epoch ints) + deleted_date for soft-delete.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.oauth2_refresh_token IS 'Persisted OAuth2 refresh-token row. PK is the refresh_token itself (varchar 255). Each row is per (refresh_token, application_id, user_id) with expires (epoch seconds) for TTL. When an app exchanges this token for a new access-token, the platform validates the (token, app, user, not-expired) combination here.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_invite IS 'Outgoing invitation for a user to join an organization. Originally defined in V3_54; re-created with the current shape in V3_55__change_table_structure_for_organization_invite.sql (the V3_54 variant was dropped CASCADE). One row per invite: organization_invite_id (uuid PK), organization_id, user_id (uuid — pre-filled when invitee already has an aiWARE account), email (varchar 255 — invitation target), message (free-text from the inviter), status (text — pending/accepted/rejected/expired), expiration_date (epoch seconds). Later migrations added created_by (V3_57), password_reset_token (V3_58), user_details JSON (V3_122), auth_group_ids text[] (V3_123), and invite_type enum (V3_124). Tracked in organization_invite__invite_action_audit; application-role grants pre-staged in organization_invite__application_roles.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_invite__application_roles IS 'Pre-staged application-role grants attached to a pending organization_invite. One row per (invite, application, role) triple: id (uuid PK), organization_invite_id FK → organization_invite, application_id FK → application, role_id FK → role. When the invitee accepts, the platform reads these rows and applies the role grants to the new user. The bulk-delete pattern (DELETE FROM … WHERE role_id = ANY($1::uuid[])) is used to clean up when an application role is itself deleted.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_invite__invite_action_audit IS 'Audit log of every action taken on an organization_invite row. One row per (invite, action, timestamp) event: id (uuid PK), organization_invite_id FK → organization_invite, action (text — e.g. created, sent, accepted, revoked), prior_status (text — the status before this action), actor (uuid of the user performing the action), timestamp (timestamp without time zone, default UTC now). Later migration V3_60 added kvp jsonb for arbitrary additional metadata and removed the audit-id FK constraint to support invite-deletion without breaking history.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_registration_configuration IS 'Configuration of an organization''s self-registration page (open-registration / SSO sign-up landing). Added in V3_122__create_registration_config.sql. One row per registration page: registration_configuration_id (uuid PK), organization_guid (uuid FK to sso_application.application_id, CASCADE on delete — note: refers to sso_application, not application, because organization identity in this context maps to the SSO-side sso_application), name/slug (slug UNIQUE — used in the public URL), open_registration_status enum (open/restricted, default restricted), admin_approval_required boolean, plus standard date_created/date_modified/created_by/modified_by audit. Files attached via organization_registration_files, UI custom via organization_registration_ui_settings, domain-specific rules via organization_registration_domain_settings.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_registration_domain_settings IS 'Per-(registration_configuration, email-domain) rule controlling which auth-group and application roles a registrant is auto-assigned to based on their email domain. Composite PK is (registration_configuration_id, domain_name). auth_group_id FK → rbac_auth_group, application_role_ids is a text array of application-role ids (no FK declared because it''s an array). Standard audit columns. CASCADE-deleted when the parent organization_registration_configuration is removed.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_registration_files IS 'Per-registration-config attached document (Terms of Service, Privacy Policy). One row per file: id (uuid PK), registration_configuration_id FK → organization_registration_configuration (CASCADE on delete), name (optional display), uri (storage URI), type (enum organization_document_type — terms_of_service / privacy_policy), status (text — lifecycle), plus the standard audit quintet (created_by/modified_by/date_created/date_modified). Added in V3_122__create_registration_config.sql.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.organization_registration_ui_settings IS 'Per-registration-config UI customization. PK and FK are the same column (registration_configuration_id) — one row per parent config (1:1). Holds logo (URI), custom_registration_fields (text — typically JSON describing extra form fields), registration_button_style (text — CSS-fragment / style name), and veritone_branding (boolean, default false — when true, the Veritone logo / footer is shown). Standard audit columns. Added in V3_122.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.permission IS 'Static permission-name catalog. Each row is one permission an app/role can require: permission_id (integer PK), permission_name (text — referenced by name in JWTs, ACL queries), permission_description (text — admin-UI display). The platform''s authz code resolves permission names → ids by reading this table (cached); apps declare permissions_required referencing these names.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
