DO $$ BEGIN COMMENT ON TABLE public.role IS 'Role-grant catalog: one row per role assignable to a user (or to invitees via organization_invite__application_roles). Carries identity (role_id uuid PK, role_name, role_description), app scope (app_name text, application_id uuid — added later), tenant scope (organization_id), visibility (is_private — when true, only the owning org sees this role), specialty flags (is_app_event_role — when true, role designates the event handler for an app), and the actual permission set (permissions integer[] — array of permission.permission_id values, default ''{}''). Heavily JOINed by every authz query that resolves user → permissions.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_acl IS 'Legacy app-level ACL grant: one row per (application, user-or-group, object_type, object_id, access) tuple. Either user_id OR group_id is set (mutually exclusive). object_type (text) and object_id (text) name the protected object; access (json) carries the permission bag. Superseded by the partitioned rbac_acl for new code paths but still actively maintained by core-admin-server/dal/acl.js.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_application IS 'SSO-side mirror of an organization: one row per "SSO application" record, which represents an org-as-tenant in the SSO subsystem. Six columns: application_id (uuid PK — note this is the org''s GUID, reused as a logical "application" id), application_name (text), date_created, kvp (json — settings bag, default {}), is_platform (boolean default true — flags Veritone platform-owned vs customer-owned orgs), organization_type_id (integer). Several other tables FK to this for org identity (e.g. organization_registration_configuration.organization_guid, user_custom_profile.organization_guid).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_external_oauth IS 'Legacy external-OAuth identity link: one row per (user, external provider) pair, storing the token issued by an external OAuth1/OAuth2 provider (Twitter, Facebook, etc.) when the user federated their account. user_id is the internal user, external_id is the provider id, external_user_id is the user''s id on the provider''s side, screen_name is the provider-side display name, token/secret are the (text) credentials. Likely largely obsolete in favor of OIDC; not actively referenced in non-test services/ SQL.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_group IS 'Application-scoped user group: one row per group within an SSO application. Carries group_id (uuid PK), group_name, application_id (uuid FK — owning app), kvp (json — settings bag, may store organizationId etc. — indexed by (kvp->>''organizationId'') for org-scoped lookup), date_created/date_modified/modified_by audit, and permissions (json default {} — permission bag distinct from the integer array on role).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_openid_connect IS 'OpenID Connect (OIDC) provider configuration: one row per OIDC IdP registered for an org (or globally). connect_id (uuid PK, default uuid_generate_v4()), owner_organization_guid (renamed from organization_guid in V3_26), name/description/website_url, credentials_ciphertext (encrypted client-secret blob), login_button_style (json — UI customization), is_global (default false — when true, the IdP is offered cross-org), use_notice (text — disclosure text on the login screen), openid_type (text default ''passport'' — implementation flavor, e.g. passport/oauth4webapi), date_created/date_modified. Later migrations added allowed_redirect_targets and external_credential_id (links to external_credential).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_openid_connect__organization IS 'OIDC provider ↔ organization grant: lets a global OIDC provider be enabled for additional orgs beyond owner_organization_guid. Three columns: connect_id (FK → sso_openid_connect.connect_id), organization_guid, enabled (boolean default true). Added in V3_26__add_table_user_openid_connect.sql alongside the sso_user__openid_connect and the column rename.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_openid_connect__role IS 'OIDC role-mapping rules per organization. PK = (organization_id, openid_role). For a given org and OIDC-provided role name (e.g. cms_editor, admin, full_access), defines role_ids (uuid array of role.role_id) and application_ids (uuid array of application.application_id) to grant when a user logs in via OIDC with that role claim. Standard audit (date_created/date_modified/modified_by). Note: existing column COMMENTs already in migration V3_36 for organization_id, openid_role, role_ids, application_ids — only date_created/date_modified/modified_by are missing.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_scim_group IS 'SCIM (System for Cross-domain Identity Management) group import. One row per group provisioned by an OIDC/SCIM IdP into a specific sso_openid_connect.connect_id. PK: group_id (uuid, default uuid_generate_v4()). Carries group_name, connect_id (FK → sso_openid_connect), group_external_id (provider-side id, e.g. Okta group id), and timestamps. UNIQUE constraint unique_scim_group_name on (group_name, connect_id) enforces no duplicate group names per IdP.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_scim_user_group IS 'SCIM user ↔ group junction: links a SCIM-provisioned user (connect_user_id text — provider-side id) to an sso_scim_group. Composite PK (group_id, connect_user_id). FK fk_scim_group_id on group_id CASCADE-deletes when the group is removed.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_token IS 'Long-lived API / service token granting access to an application (and optionally a group within it). One row per issued token: token_id (text PK — opaque token value), application_id (uuid FK, optional), group_id (uuid FK, optional), json (json — token claims / scope bag), token_hash (added later — hash of the token for fast indexed lookup since token_id itself is too long to index efficiently). Has a CHECK constraint token_check requiring char_length(token_id) > 36 AND strpos(token_id, '':'') > 0 (i.e. token format <prefix>:<random>).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_user IS 'Core user identity row. One row per Veritone user account. Carries identity (user_id uuid PK, user_name text — email or login id, password text — hashed credential), audit (date_created/date_modified/modified_by/last_logged_in), settings (kvp json — free-form, user_settings json default {}), lifecycle (status enum user_status default active), and security state: password_reset_token, password_change_required boolean, activation_token, trial_token, MFA (mfa_shared_secret/mfa_phone_number/mfa_verified_date/mfa_default_option/mfa_ga_shared_secret/mfa_ga_verified_date/mfa_pending_registration), date_password_last_updated. Later additions: email (separate from user_name for cases where username ≠ email), system_user boolean (default false — added in V3_41; designates a non-human service account, e.g. an event-handler bot). PII-heavy table — never log password, *token, mfa*.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_user__openid_connect IS 'User ↔ OIDC-provider identity link: one row per (user, OIDC provider) federation. Added in V3_26__add_table_user_openid_connect.sql. Carries user_id (FK → sso_user.user_id), connect_id (FK → sso_openid_connect.connect_id), connect_user_id (text — provider-side user identifier; existing column COMMENT in V3_26), connect_type (text — provider type like google/azure-ad/github; existing COMMENT), kvp (json — synced provider claims; existing COMMENT), and date_created. Two FK constraints declared (_fk_sso_user__openid_connect@user_id, _fk_sso_user__openid_connect@connect_id). A date_modified and identifier_id are added in later migrations.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_user__scim_connect_id IS 'User ↔ SCIM external-id link. Added in V3_40__create_sso_user_scim_connect_table_id.sql to support multiple SCIM external-ids per user (replaced an earlier single-column scim_connect_id on sso_user). Three columns: row_id (uuid PK, default uuid_generate_v4()), user_id (FK → sso_user.user_id, CASCADE on delete), scim_connect_id (uuid — the SCIM-side external id). UNIQUE constraint on (user_id, scim_connect_id).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_user__sso_group IS 'User ↔ group membership: one row per (user, group) pair. Original two-column V1_01 shape: user_id (uuid) + group_id (uuid). V3_02__add_priority_to_sso_user__sso_group.sql added priority smallint default 0 (lower number wins when resolving the user''s "primary" group; the next_priority($3) function on insert picks the next slot). Later migrations added last_logged_in and created_date_time. A unique index on (user_id, group_id, priority) (V3_11) enforces priority uniqueness within the user''s groups.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.sso_user_role IS 'User ↔ role grant. One row per (user, role) assignment with optional app scope. Five columns: user_id (uuid FK → sso_user), role_id (uuid FK → role), date_created (timestamp(3), default now()), created_by (uuid — admin who granted), application_id (uuid, added later — for app-scoped grants). Heavily queried by the authz layer to resolve user → roles → permissions.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.trial IS 'Trial-period tracking row. One row per active trial: trial_id (uuid identifier, unique per trial instance), user_id (FK → sso_user), date_activated / date_end (window), trial_duration (integer days/hours per app convention). Used by admin tooling to detect trial-expiry events and to display "X days left" badges in the UI.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.user_custom_profile IS 'Per-(user, org) custom-profile text blob. Added in V3_122__create_registration_config.sql. Five columns: user_id (FK → sso_user, CASCADE on delete), organization_guid (FK → sso_application.application_id, CASCADE), custom_profile (text — typically JSON, captures the answers to the custom_registration_fields defined on the registration page), and date_created/date_modified timestamps.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.user_history IS 'Per-user key-value history store. Added in V3_06__user_history.sql. Three columns: user_id (uuid FK → sso_user), key (text — discriminator e.g. last_password, last_login_ip), value (text — the stored value). Multi-row design (no UNIQUE on (user_id, key)) means multiple historical values can be retained for a single key. Used by core-admin-server/dal/user-history.js to track sensitive previous-state for audit / replay-protection (e.g. previous password hashes).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.user_setting IS 'Per-(user, key) settings KV. Original V1_01 shape: user_id (uuid), key (text), value (text — no PK/UNIQUE declared; rely on app-side write-through). Later migration V3_23__application_setting_table.sql added application_id uuid DEFAULT NULL plus FK _fk_user_setting__application_id → application to scope settings to a specific app.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE rate_limit.config_organization IS 'Per-organization rate-limit override. One row per org: organization_id (text — note: text, not integer), created_date_time/modified_date_time (timestamptz), interval_limit (integer — requests-per-interval cap). The most-recently-modified row wins; core-graphql-server/rateLimit.js reads the full table on init and refreshes periodically (sorted by modified_date_time DESC).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE rate_limit.config_organization_engine IS 'Per-(organization, engine) rate-limit override. Same column shape as config_organization but adds an implicit engine scope (the engine name typically piggybacks on organization_id or is encoded in a separate column added later — confirm against current production DDL). The interval_limit here applies when the request is targeted at a specific engine for that org.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE rate_limit.config_settings IS 'Global rate-limit settings. Loaded once by core-graphql-server/rateLimit.js:160 (SELECT * FROM rate_limit.config_settings ORDER BY modified_date_time DESC). Key-value style: setting_key (text — e.g. default_interval_seconds, burst_multiplier), interval_limit (integer — the value), plus standard created_date_time / modified_date_time timestamps.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE rate_limit.config_token IS 'Per-token rate-limit override. One row per API token: token_id (text — references sso_token.token_id semantically though no FK), interval_limit (integer cap), timestamps. Loaded by core-graphql-server/rateLimit.js:109 (SELECT * FROM rate_limit.config_token ORDER BY modified_date_time DESC).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE rate_limit.config_token_type IS 'Per-token-type rate-limit default. One row per token kind: token_type (text — e.g. service, user_session, api_key), interval_limit (integer cap), timestamps. Loaded by core-graphql-server/rateLimit.js:144 (SELECT * FROM rate_limit.config_token_type ORDER BY modified_date_time DESC).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;

